((SELECT id FROM dishes WHERE slug='xiaolongbao'),4,'A thin dough purse pleated shut around minced pork and a jellied broth that melts when steamed.'),
((SELECT id FROM dishes WHERE slug='xiaolongbao'),5,'The soup-filled steamed dumpling of Shanghai.'),
((SELECT id FROM dishes WHERE slug='congee'),1,'A breakfast bowl found across East Asia, endlessly customizable.'),
((SELECT id FROM dishes WHERE slug='congee'),2,'Rice porridge has fed China for over two thousand years, especially the sick and the very young.'),
