((SELECT id FROM dishes WHERE slug='congee'),4,'Rice is simmered for hours in broth until it breaks down into a silky porridge, topped with shredded meat.'),
((SELECT id FROM dishes WHERE slug='congee'),5,'The slow-simmered rice porridge of China.'),
((SELECT id FROM dishes WHERE slug='char-siu'),1,'A glossy roasted meat that hangs in Chinatown windows worldwide.'),
