((SELECT id FROM dishes WHERE slug='char-siu'),5,'Cantonese honey-glazed roast pork.'),
((SELECT id FROM dishes WHERE slug='dan-dan-noodles'),1,'A numbing noodle dish named for the pole it was once carried on.'),
